-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Tests > - Maßnahmen > - Refactoring

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Refactoring in der testgetriebenen Entwicklung (TDD) ohne bestehende Tests sicher durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Tests sichern Funktionalität bei Änderungen"}, {"text": "Ja", "correct": false, "because": "Ohne Tests besteht Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Refactoring in TDD darauf ausgelegt, die Funktionalität der Software zu verändern?', 2, '[{"text": "Nein", "correct": true, "because": "Refactoring verbessert Struktur, nicht Funktion"}, {"text": "Ja", "correct": false, "because": "Funktion bleibt erhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Refactoring-Maßnahmen in TDD die Lesbarkeit des Codes verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Lesbarkeit ist ein Hauptziel"}, {"text": "Nein", "correct": false, "because": "Strukturverbesserung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Refactoring in TDD immer nach jedem erfolgreichen Test durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Bedarf an Strukturverbesserung"}, {"text": "Ja", "correct": false, "because": "Flexibel im Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Refactoring in TDD ohne Auswirkung auf die Testfälle stattfinden?', 2, '[{"text": "Ja", "correct": true, "because": "Funktion bleibt, Tests bestehen"}, {"text": "Nein", "correct": false, "because": "Tests unbeeinflusst möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt Refactoring in TDD?', 2, '[{"text": "Verbesserung der Code-Struktur", "correct": true, "because": "Struktur ohne Funktionsänderung"}, {"text": "Erweiterung der Funktionalität", "correct": false, "because": "Nicht Refactoring-Ziel"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt im TDD-Zyklus folgt typischerweise auf die Fehlerbehebung und führt zu Refactoring?', 3, '[{"text": "Grün-Phase", "correct": true, "because": "Erfolgreiche Tests ermöglichen Refactoring"}, {"text": "Rot-Phase", "correct": false, "because": "Fehleridentifikation"}, {"text": "Testfallerstellung", "correct": false, "because": "Vor Fehlerbehebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug ist in TDD entscheidend, um die Korrektheit nach dem Refactoring zu sichern?', 2, '[{"text": "Test-Suite", "correct": true, "because": "Überprüft Funktionalität"}, {"text": "Compiler", "correct": false, "because": "Nur Syntax"}, {"text": "Debugger", "correct": false, "because": "Fehleranalyse, nicht Sicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt wird durch Refactoring in TDD primär verbessert?', 2, '[{"text": "Wartbarkeit", "correct": true, "because": "Bessere Struktur erleichtert Änderungen"}, {"text": "Laufzeit", "correct": false, "because": "Nicht primär"}, {"text": "Funktionalität", "correct": false, "because": "Bleibt gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip leitet Refactoring in TDD?', 2, '[{"text": "Funktionalität erhalten", "correct": true, "because": "Änderung nur strukturell"}, {"text": "Maximale Code-Reduktion", "correct": false, "because": "Nicht zwingend"}, {"text": "Manuelle Optimierung", "correct": false, "because": "Tests sichern"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Ziele verfolgt Refactoring in TDD?', 4, '[{"text": "Verbesserung der Lesbarkeit", "correct": true, "because": "Klarer Code"}, {"text": "Reduzierung der Komplexität", "correct": true, "because": "Einfachere Struktur"}, {"text": "Erweiterung der Funktionalität", "correct": false, "because": "Nicht Refactoring-Ziel"}, {"text": "Erhöhung der Wartbarkeit", "correct": true, "because": "Langfristige Pflege"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen sind für ein sicheres Refactoring in TDD nötig?', 3, '[{"text": "Bestehende Test-Suite", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Erfolgreiche Tests", "correct": true, "because": "Grün-Phase erforderlich"}, {"text": "Keine Tests nötig", "correct": false, "because": "Tests essenziell"}, {"text": "Klarer Refactoring-Plan", "correct": true, "because": "Strukturierte Änderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken werden beim Refactoring in TDD häufig angewendet?', 3, '[{"text": "Umbenennen von Variablen", "correct": true, "because": "Verbessert Lesbarkeit"}, {"text": "Aufteilen von Funktionen", "correct": true, "because": "Reduziert Komplexität"}, {"text": "Hinzufügen neuer Features", "correct": false, "because": "Nicht Refactoring"}, {"text": "Entfernen von Redundanzen", "correct": true, "because": "Optimiert Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Refactoring in TDD?', 4, '[{"text": "Bessere Codequalität", "correct": true, "because": "Struktur verbessert"}, {"text": "Einfachere Wartung", "correct": true, "because": "Klarheit erleichtert"}, {"text": "Höhere Entwicklungskosten", "correct": false, "because": "Kosten oft gesenkt"}, {"text": "Vermeidung technischer Schulden", "correct": true, "because": "Struktur bleibt sauber"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es beim Refactoring in TDD ohne Tests?', 3, '[{"text": "Funktionsverlust", "correct": true, "because": "Keine Sicherung"}, {"text": "Einführung neuer Fehler", "correct": true, "because": "Unbemerkte Änderungen"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Eher Verzögerung"}, {"text": "Unentdeckte Regressionsfehler", "correct": true, "because": "Tests fehlen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Refactoring in TDD ändert die Softwarefunktionalität. b) Tests sichern die Korrektheit nach Refactoring.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Funktion bleibt, Tests prüfen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Refactoring in TDD erfolgt vor der Grün-Phase. b) Refactoring verbessert die Wartbarkeit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Refactoring nach Grün, Wartbarkeit steigt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Refactoring in TDD ist ohne Tests sicher. b) Refactoring reduziert technische Schulden.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Tests nötig, Schulden sinken"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Refactoring in TDD kann die Lesbarkeit verbessern. b) Refactoring ist in TDD nach jedem Test zwingend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lesbarkeit steigt, nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Refactoring in TDD erfordert keine Test-Suite. b) Refactoring kann ohne Funktionsverlust erfolgen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Tests nötig, Funktion erhalten"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

